function renderAt(path: string) {
  render(
    <MemoryRouter initialEntries={[path]}>
      <App />
    </MemoryRouter>
  );
}

/**
 * Helper to fill the contact form fields.
 */
function fillForm({
  name = '',
  email = '',
  company = '',
  request = '',
  message = '',
}: {
  name?: string;
  email?: string;
  company?: string;
  request?: string;
  message?: string;
}) {
